<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
$quoteConfig = [];
$configPath = dirname(__DIR__, 2) . DIRECTORY_SEPARATOR . 'quote-config.php';
if (is_file($configPath)) { $loaded = require $configPath; if (is_array($loaded)) $quoteConfig = $loaded; }
function respond(int $status, array $payload): void { http_response_code($status); echo json_encode($payload); exit; }
function env_value(string $name, string $fallback = ''): string { global $quoteConfig; $value = getenv($name); if ($value === false && isset($_SERVER[$name])) $value = $_SERVER[$name]; if (($value === false || $value === '') && isset($quoteConfig[$name])) $value = $quoteConfig[$name]; return trim((string)($value === false ? $fallback : $value)); }
function text_value(array $body, string $key, int $limit = 500): string { return mb_substr(trim((string)($body[$key] ?? '')), 0, $limit); }
if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') { header('Allow: POST'); respond(405, ['error' => 'Method not allowed.']); }
if ((int)($_SERVER['CONTENT_LENGTH'] ?? 0) > 64 * 1024) respond(413, ['error' => 'The quote request is too large.']);
$origins = array_values(array_filter(array_map('trim', explode(',', env_value('QUOTE_ALLOWED_ORIGINS')))));
$origin = trim((string)($_SERVER['HTTP_ORIGIN'] ?? ''));
if ($origins && $origin && !in_array($origin, $origins, true)) respond(403, ['error' => 'This website is not allowed to submit quote requests.']);
$body = json_decode((string)file_get_contents('php://input'), true);
if (!is_array($body)) respond(400, ['error' => 'The quote request is invalid.']);
if (text_value($body, 'website') !== '') respond(200, ['ok' => true]);
$name = text_value($body, 'name', 120); $email = strtolower(text_value($body, 'email', 254)); $phone = text_value($body, 'phone', 60); $pickup = text_value($body, 'pickup', 180); $delivery = text_value($body, 'delivery', 180);
if ($name === '' || $phone === '' || $pickup === '' || $delivery === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) respond(400, ['error' => 'Please complete all required fields with a valid email address.']);
$apiKey = env_value('RESEND_API_KEY'); $fromEmail = env_value('RESEND_FROM_EMAIL'); $recipient = env_value('QUOTE_RECIPIENT_EMAIL', $fromEmail); $fromName = env_value('RESEND_FROM_NAME', 'A11 Freight');
if ($apiKey === '' || !filter_var($fromEmail, FILTER_VALIDATE_EMAIL) || !filter_var($recipient, FILTER_VALIDATE_EMAIL)) { error_log('Quote endpoint: Resend configuration is missing or invalid.'); respond(500, ['error' => 'The quote email service is not configured.']); }
$details = ['Name' => $name, 'Company' => text_value($body, 'company', 160) ?: 'Not provided', 'Email' => $email, 'Phone' => $phone, 'Pickup date' => text_value($body, 'pickupDate', 30) ?: 'Not provided', 'Freight type' => text_value($body, 'freightType', 80) ?: 'Not specified', 'Pallets / pieces' => text_value($body, 'pallets', 30) ?: 'Not provided', 'Weight (lb)' => text_value($body, 'weight', 30) ?: 'Not provided', 'Dimensions' => text_value($body, 'dimensions', 160) ?: 'Not provided'];
$rows = ''; $rowIndex = 0; $rowCount = count($details); foreach ($details as $label => $value) { $rowIndex++; $border = $rowIndex === $rowCount ? '0' : '1px solid #e8edf2'; $rows .= '<tr><td style="width:38%;padding:13px 16px;border-bottom:' . $border . ';color:#667085;font-size:13px;font-weight:700;vertical-align:top">' . htmlspecialchars($label, ENT_QUOTES, 'UTF-8') . '</td><td style="padding:13px 16px;border-bottom:' . $border . ';color:#17212b;font-size:14px;font-weight:600;line-height:1.5;white-space:pre-wrap;vertical-align:top">' . htmlspecialchars($value, ENT_QUOTES, 'UTF-8') . '</td></tr>'; }
$safeName = htmlspecialchars($name, ENT_QUOTES, 'UTF-8'); $safeEmail = htmlspecialchars($email, ENT_QUOTES, 'UTF-8'); $safePickup = htmlspecialchars($pickup, ENT_QUOTES, 'UTF-8'); $safeDelivery = htmlspecialchars($delivery, ENT_QUOTES, 'UTF-8'); $safeNotes = htmlspecialchars(text_value($body, 'notes', 3000) ?: 'None', ENT_QUOTES, 'UTF-8');
$html = '<!doctype html><html><body style="margin:0;padding:0;background:#f3f5f7;font-family:Arial,Helvetica,sans-serif;color:#17212b"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f3f5f7"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:640px;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 8px 30px rgba(23,33,43,.10)"><tr><td style="padding:30px 34px;background:#1f2933;border-bottom:5px solid #bc7049"><div style="color:#efb08f;font-size:11px;font-weight:800;letter-spacing:2.2px;text-transform:uppercase">A11 Freight</div><h1 style="margin:8px 0 6px;color:#fff;font-size:26px">New quote request</h1><p style="margin:0;color:#d5dce3;font-size:14px">A new shipment enquiry is ready for review.</p></td></tr><tr><td style="padding:28px 30px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin-bottom:22px"><tr><td style="padding:18px 20px;background:#fff4ee;border-left:4px solid #bc7049;border-radius:8px"><div style="color:#9a5230;font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase">Route</div><div style="margin-top:6px;color:#17212b;font-size:18px;font-weight:800">' . $safePickup . ' <span style="color:#bc7049">&rarr;</span> ' . $safeDelivery . '</div></td></tr></table><h2 style="margin:0 0 10px;color:#1f2933;font-size:15px">Quote details</h2><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin-bottom:24px;border:1px solid #e8edf2;border-radius:10px;border-collapse:separate;overflow:hidden">' . $rows . '</table><h2 style="margin:0 0 10px;color:#1f2933;font-size:15px">Additional notes</h2><div style="padding:16px;background:#f7f9fb;border:1px solid #e8edf2;border-radius:10px;color:#344054;font-size:14px;line-height:1.6;white-space:pre-wrap">' . $safeNotes . '</div><table role="presentation" cellspacing="0" cellpadding="0" style="margin-top:26px"><tr><td style="border-radius:8px;background:#bc7049"><a href="mailto:' . $safeEmail . '" style="display:inline-block;padding:13px 22px;color:#fff;text-decoration:none;font-size:14px;font-weight:800">Reply to ' . $safeName . '</a></td></tr></table></td></tr><tr><td style="padding:18px 30px;background:#1f2933;color:#aeb8c2;font-size:11px">Submitted through the A11 Freight website quote form.</td></tr></table></td></tr></table></body></html>';
$payload = ['from' => $fromName . ' <' . $fromEmail . '>', 'to' => [$recipient], 'reply_to' => $email, 'subject' => 'New freight quote request — ' . $pickup . ' to ' . $delivery, 'html' => $html];
$curl = curl_init('https://api.resend.com/emails'); curl_setopt_array($curl, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => ['Authorization: Bearer ' . $apiKey, 'Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload), CURLOPT_TIMEOUT => 20]);
$result = curl_exec($curl); $curlError = curl_error($curl); $status = (int)curl_getinfo($curl, CURLINFO_HTTP_CODE); curl_close($curl);
if ($result === false || $status < 200 || $status >= 300) { error_log('Quote endpoint: Resend failed with HTTP ' . $status . ': ' . ($curlError ?: (string)$result)); respond(502, ['error' => 'We could not send your request. Please try again or email info@a11freight.com.']); }
$resendResult = json_decode((string)$result, true); respond(200, ['ok' => true, 'id' => $resendResult['id'] ?? null]);
